import 'dart:convert';
import 'dart:typed_data';

Uint8List previewPdf() {
  final objects = <String>[
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << /Font << /F1 5 0 R >> >> /Contents 6 0 R >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << /Font << /F1 5 0 R >> >> /Contents 7 0 R >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
    for (final text in ['Native PDF first page', 'Native PDF second page'])
      '<< /Length ${'BT /F1 20 Tf 25 100 Td ($text) Tj ET'.length} >>\nstream\nBT /F1 20 Tf 25 100 Td ($text) Tj ET\nendstream',
  ];
  var body = '%PDF-1.4\n';
  final offsets = <int>[0];
  for (var i = 0; i < objects.length; i++) {
    offsets.add(body.length);
    body += '${i + 1} 0 obj\n${objects[i]}\nendobj\n';
  }
  final xref = body.length;
  body += 'xref\n0 ${offsets.length}\n0000000000 65535 f \n';
  for (final offset in offsets.skip(1)) {
    body += '${offset.toString().padLeft(10, '0')} 00000 n \n';
  }
  body +=
      'trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n$xref\n%%EOF\n';
  return Uint8List.fromList(ascii.encode(body));
}

Uint8List previewWav() {
  const samples = 16000 * 3;
  final data = ByteData(44 + samples * 2);
  void word(int offset, String text) {
    for (var i = 0; i < text.length; i++) {
      data.setUint8(offset + i, text.codeUnitAt(i));
    }
  }

  word(0, 'RIFF');
  data.setUint32(4, 36 + samples * 2, Endian.little);
  word(8, 'WAVE');
  word(12, 'fmt ');
  data.setUint32(16, 16, Endian.little);
  data.setUint16(20, 1, Endian.little);
  data.setUint16(22, 1, Endian.little);
  data.setUint32(24, 16000, Endian.little);
  data.setUint32(28, 32000, Endian.little);
  data.setUint16(32, 2, Endian.little);
  data.setUint16(34, 16, Endian.little);
  word(36, 'data');
  data.setUint32(40, samples * 2, Endian.little);
  // Silent bounded PCM avoids unexpected sound in an automated acceptance run.
  return data.buffer.asUint8List();
}

